Q: Modern .NET - Self installing a Windows Service A: <p>In the last 16 months since I posed this question, I made some progress.</p>
<p>I started from the code in the TopShelf library, and I discovered that the crux of the install / uninstall procedures lies in just a few calls to Windows API (it is always WinAPI, isn't it?).</p>
<p>Currently I have this code, but we are going to test it in this period, so consider it just a starting point:</p>
<pre class="lang-cs prettyprint-override"><code>using System;
using System.ComponentModel;
using System.Runtime.InteropServices;
using System.ServiceProcess;
using System.Text;
using System.Threading;

namespace InstallationUtils.WinService;

public static class WindowsServiceInstaller
{
    public static ApplicationActionResult Install(WindowsServiceConfiguration config, string commandLine)
    {
        if (config == null) throw new ArgumentNullException(nameof(config));

        if (config.ServiceAccount == ServiceAccount.User) GrantAccountRights(config);
        InstallService(config, commandLine);

        return ApplicationActionResult.Ok(&quot;Not implemented&quot;);
    }

    public static void InstallService(WindowsServiceConfiguration config, string commandLine)
    {
        if (string.IsNullOrEmpty(commandLine)) throw new ArgumentNullException(nameof(commandLine));

        var (userName, password) = ReadCredentialsFromConfiguration(config);

        // Put quotas around module file name. Otherwise a service might fail to start if there is space in the path.
        // Note: CreateService accepts a binaryPath allowing arguments for automatic services, in /assemblypath=foo,
        // foo is simply the path to the executable.
        // Therefore, it is best to quote if there are no quotes, and best to not quote if there are quotes.
        if (commandLine.IndexOf('\&quot;') == -1) commandLine = &quot;\&quot;&quot; + commandLine + &quot;\&quot;&quot;;

        // TODO: Check service name and DisplayName length. 

        // Open the service manager
        var serviceManagerHandle = OpenScManager();
        var serviceHandle = IntPtr.Zero;

        try
        {
            // Install the service
            serviceHandle = NativeMethods.CreateService(
                serviceManagerHandle,
                config.Name,
                config.DisplayName,
                NativeMethods.ACCESS_TYPE_ALL,
                NativeMethods.SERVICE_TYPE_WIN32_OWN_PROCESS,
                (int)config.StartMode,
                NativeMethods.ERROR_CONTROL_NORMAL,
                commandLine,
                null, // loadOrderGroup
                IntPtr.Zero, // pTagId
                null, // dependencies
                userName,
                password
            );

            if (serviceHandle == IntPtr.Zero) throw new Win32Exception();

            // A local variable in an unsafe method is already fixed -- so we don't need a &quot;fixed { }&quot; blocks to protect 
            // across the p/invoke calls below.

            if (!string.IsNullOrEmpty(config.Description))
            {
                var serviceDesc = new NativeMethods.SERVICE_DESCRIPTION();
                serviceDesc.description = Marshal.StringToHGlobalUni(config.Description);
                uint serviceCfg = NativeMethods.SERVICE_CONFIG_DESCRIPTION;
                var success = NativeMethods.ChangeServiceConfig2(serviceHandle, serviceCfg, ref serviceDesc);
                Marshal.FreeHGlobal(serviceDesc.description);
                if (!success) throw new Win32Exception();
            }

            if (Environment.OSVersion.Version.Major &gt; 5 &amp;&amp; config.StartMode == ServiceStartMode.Automatic)
            {
                var serviceDelayedInfo = new NativeMethods.SERVICE_DELAYED_AUTOSTART_INFO
                {
                    fDelayedAutostart = config.DelayedAutoStart
                };
                uint serviceCfg = NativeMethods.SERVICE_CONFIG_DELAYED_AUTO_START_INFO;
                var success = NativeMethods.ChangeServiceConfig2(serviceHandle, serviceCfg, ref serviceDelayedInfo);
                if (!success) throw new Win32Exception();
            }
        }
        finally
        {
            if (serviceHandle != IntPtr.Zero) SafeNativeMethods.CloseServiceHandle(serviceHandle);

            SafeNativeMethods.CloseServiceHandle(serviceManagerHandle);
        }

        // Context.LogMessage(Res.GetString(Res.InstallOK, ServiceName));
    }

    private const string NETWORK_SERVICE_NAME = &quot;NT AUTHORITY\\NetworkService&quot;;

    private const string LOCAL_SERVICE_NAME = &quot;NT AUTHORITY\\LocalService&quot;;

    private static (string user, string pwd) ReadCredentialsFromConfiguration(WindowsServiceConfiguration config)
    {
        switch (config.ServiceAccount)
        {
            case ServiceAccount.LocalService:
                return (LOCAL_SERVICE_NAME, null);
            case ServiceAccount.NetworkService:
                return (NETWORK_SERVICE_NAME, null);
            case ServiceAccount.User:
                return (config.UserName, config.Password);
            default:
                return (null, null);
        }
    }

    private static void GrantAccountRights(WindowsServiceConfiguration config)
    {
        if (config?.ServiceAccount != ServiceAccount.User) return;

        var intPtr = OpenSecurityPolicy();
        try
        {
            var accountSid = GetAccountSid(config.UserName);
            var accountHasRight = AccountHasRight(intPtr, accountSid, &quot;SeServiceLogonRight&quot;);
            if (!accountHasRight)
            {
                GrantAccountRight(intPtr, accountSid, &quot;SeServiceLogonRight&quot;);
            }
        }
        finally
        {
            SafeNativeMethods.LsaClose(intPtr);
        }
    }

    private static IntPtr OpenSecurityPolicy()
    {
        var attributes = new NativeMethods.LSA_OBJECT_ATTRIBUTES();
        var attributesHandle = GCHandle.Alloc(attributes, GCHandleType.Pinned);
        try
        {
            var attributesPointer = attributesHandle.AddrOfPinnedObject();
            var desiredAccess = NativeMethods.POLICY_CREATE_ACCOUNT | NativeMethods.POLICY_LOOKUP_NAMES;
            var result = NativeMethods.LsaOpenPolicy(null, attributesPointer, desiredAccess, out var policyHandle);
            if (result != 0) throw new Win32Exception(SafeNativeMethods.LsaNtStatusToWinError(result));

            return policyHandle;
        }
        finally
        {
            attributesHandle.Free();
        }
    }

    private static byte[] GetAccountSid(string accountName)
    {
        //Lookup SID
        var newSid = new byte[256];
        var sidLen = new int[] { newSid.Length };
        var domName = new char[1024];
        var domNameLen = new int[] { domName.Length };
        var peUse = new int[1];
        bool success;

        if (accountName.Substring(0, 2) == &quot;.\\&quot;)
        {
            // Replace the &quot;.&quot; with the local computer name.
            var compName = new StringBuilder(NativeMethods.MAX_COMPUTERNAME_LENGTH + 1);
            var nameLen = NativeMethods.MAX_COMPUTERNAME_LENGTH + 1;
            success = NativeMethods.GetComputerName(compName, ref nameLen);
            if (!success) throw new Win32Exception();

            accountName = compName + accountName.Substring(1);
        }

        success = NativeMethods.LookupAccountName(null, accountName, newSid, sidLen, domName, domNameLen, peUse);
        if (!success)
            throw new Win32Exception();

        var sid = new byte[sidLen[0]];
        Array.Copy(newSid, 0, sid, 0, sidLen[0]);
        return sid;
    }


    /// &lt;summary&gt;
    /// Enumerates through the rights of the given account and checks whether the given right
    /// is in the list.
    /// &lt;/summary&gt;
    private static bool AccountHasRight(IntPtr policyHandle, byte[] accountSid, string rightName)
    {
        // This function gives us back a pointer to the start of an array of LSA_UNICODE_STRING structs (in pRights).
        var status =
            NativeMethods.LsaEnumerateAccountRights(policyHandle, accountSid, out var pRights, out var rightsCount);

        // this means that the accountSid has no specific rights 
        if (status == NativeMethods.STATUS_OBJECT_NAME_NOT_FOUND)
            return false;

        if (status != 0)
            throw new Win32Exception(SafeNativeMethods.LsaNtStatusToWinError(status));

        try
        {
            // look through the rights and see if the desired one is present.
            var pCurRights = pRights;
            for (var i = 0; i &lt; rightsCount; i++)
            {
                // Get this element in the array they gave us
                var uStr = new NativeMethods.LSA_UNICODE_STRING_withPointer();
                // copy the buffer portion to an array &amp; create a string from that
                Marshal.PtrToStructure(pCurRights, uStr);
                var rightChars = new char[uStr.length / sizeof(char)];
                Marshal.Copy(uStr.pwstr, rightChars, 0, rightChars.Length);
                var right = new string(rightChars, 0, rightChars.Length);
                // see if this is the one we're looking for
                if (string.Compare(right, rightName, StringComparison.Ordinal) == 0)
                    return true;

                // move to the next element in the array
                pCurRights = (IntPtr)((long)pCurRights + Marshal.SizeOf(typeof(NativeMethods.LSA_UNICODE_STRING)));
            }

            return false;
        }
        finally
        {
            // make sure we free the memory they allocated for us
            SafeNativeMethods.LsaFreeMemory(pRights);
        }
    }

    private static void GrantAccountRight(IntPtr policyHandle, byte[] accountSid, string rightName)
    {
        var byteLength = (short)(rightName.Length * 2);
        var userRights = new NativeMethods.LSA_UNICODE_STRING
            { buffer = rightName, length = byteLength, maximumLength = byteLength };
        var lsaNtStatus = NativeMethods.LsaAddAccountRights(policyHandle, accountSid, userRights, 1);

        if (lsaNtStatus != 0) throw new Win32Exception(SafeNativeMethods.LsaNtStatusToWinError(lsaNtStatus));
    }

    public static ApplicationActionResult Uninstall(string serviceName)
    {
        return ApplicationActionResult.Ko(&quot;Not implemented&quot;);
    }

    private static void RemoveService(string serviceName)
    {
        //Context.LogMessage(Res.GetString(Res.ServiceRemoving, ServiceName));
        var serviceManagerHandle = OpenScManager();

        var serviceHandle = IntPtr.Zero;
        try
        {
            serviceHandle = NativeMethods.OpenService(serviceManagerHandle,
                serviceName, NativeMethods.STANDARD_RIGHTS_DELETE);

            if (serviceHandle == IntPtr.Zero)
                throw new Win32Exception();

            NativeMethods.DeleteService(serviceHandle);
        }
        finally
        {
            if (serviceHandle != IntPtr.Zero)
                SafeNativeMethods.CloseServiceHandle(serviceHandle);

            SafeNativeMethods.CloseServiceHandle(serviceManagerHandle);
        }
        //Context.LogMessage(Res.GetString(Res.ServiceRemoved, ServiceName));

        // Stop the service
        try
        {
            using (var svc = new ServiceController(serviceName))
            {
                if (svc.Status != ServiceControllerStatus.Stopped)
                {
                    //Context.LogMessage(Res.GetString(Res.TryToStop, ServiceName));
                    svc.Stop();
                    var timeout = 10;
                    svc.Refresh();
                    while (svc.Status != ServiceControllerStatus.Stopped &amp;&amp; timeout &gt; 0)
                    {
                        Thread.Sleep(1000);
                        svc.Refresh();
                        timeout--;
                    }
                }
            }
        }
        catch
        {
        }

        Thread.Sleep(5000);
    }

    private static IntPtr OpenScManager()
    {
        var serviceManagerHandle = SafeNativeMethods.OpenSCManager(null, null, NativeMethods.SC_MANAGER_ALL);
        if (serviceManagerHandle == IntPtr.Zero)
            throw new InvalidOperationException(&quot;Error opening service control manager.&quot;, new Win32Exception());
        return serviceManagerHandle;
    }
}


/// &lt;summary&gt;Result of an executed application action.&lt;/summary&gt;
public class ApplicationActionResult
{
    /// &lt;summary&gt;True if the action completed successfully.&lt;/summary&gt;
    public bool Success { get; set; }

    /// &lt;summary&gt;String describing the result of the action.&lt;/summary&gt;
    public string Message { get; set; }

    public static ApplicationActionResult Ok(string message) =&gt; new() { Success = true, Message = message };
    public static ApplicationActionResult Ok() =&gt; new() { Success = true, Message = &quot;Ok&quot; };
    public static ApplicationActionResult Ko(string message) =&gt; new() { Success = false, Message = message };
    public static ApplicationActionResult Ko() =&gt; new() { Success = false, Message = &quot;Unspecified error&quot; };
}


/// &lt;summary&gt;Specifies a service's security context, which defines its logon type.&lt;/summary&gt;
public enum ServiceAccount
{
    /// &lt;summary&gt;An account that acts as a non-privileged user on the local computer, and presents anonymous credentials to any remote server.&lt;/summary&gt;
    LocalService,

    /// &lt;summary&gt;An account that provides extensive local privileges, and presents the computer's credentials to any remote server.&lt;/summary&gt;
    NetworkService,

    /// &lt;summary&gt;An account, used by the service control manager, that has extensive privileges on the local computer and acts as the computer on the network.&lt;/summary&gt;
    LocalSystem,

    /// &lt;summary&gt;An account defined by a specific user on the network. Specifying &lt;see langword=&quot;User&quot; /&gt; for the
    /// &lt;see cref=&quot;P:System.ServiceProcess.ServiceProcessInstaller.Account&quot; /&gt; member causes the system to prompt
    /// for a valid user name and password when the service is installed, unless you set values for both the
    /// &lt;see cref=&quot;P:System.ServiceProcess.ServiceProcessInstaller.Username&quot; /&gt; and &lt;see cref=&quot;P:System.ServiceProcess.ServiceProcessInstaller.Password&quot; /&gt;
    /// properties of your &lt;see cref=&quot;T:System.ServiceProcess.ServiceProcessInstaller&quot; /&gt; instance.&lt;/summary&gt;
    User,
}

/// &lt;summary&gt;Indicates the start mode of the service.&lt;/summary&gt;
public enum ServiceStartMode
{
    /// &lt;summary&gt;Indicates that the service is a device driver started by the system loader. This value is valid only for device drivers.&lt;/summary&gt;
    Boot,
    /// &lt;summary&gt;Indicates that the service is a device driver started by the &lt;see langword=&quot;IOInitSystem&quot; /&gt; function. This value is valid only for device drivers.&lt;/summary&gt;
    System,
    /// &lt;summary&gt;Indicates that the service is to be started (or was started) by the operating system, at system start-up. If an automatically started service depends on a manually started service, the manually started service is also started automatically at system startup.&lt;/summary&gt;
    Automatic,
    /// &lt;summary&gt;Indicates that the service is started only manually, by a user (using the Service Control Manager) or by an application.&lt;/summary&gt;
    Manual,
    /// &lt;summary&gt;Indicates that the service is disabled, so that it cannot be started by a user or application.&lt;/summary&gt;
    Disabled,
}

/// &lt;summary&gt;Class used to store the configuration information of a Windows Service.&lt;/summary&gt;
public class WindowsServiceConfiguration
{
    /// &lt;summary&gt; The name of the application. &lt;/summary&gt;
    public string Name { get; set; }

    /// &lt;summary&gt; The displayable name that shows in application manager (defaults to Name). &lt;/summary&gt;
    public string DisplayName { get; set; }

    /// &lt;summary&gt; A textural description of the application name (defaults to Name). &lt;/summary&gt;
    public string Description { get; set; }

    /// &lt;summary&gt; The System Account to be used, when no credentials are specified. &lt;/summary&gt;
    public ServiceAccount ServiceAccount { get; set; } = ServiceAccount.LocalSystem;

    /// &lt;summary&gt; The user to run the application under (defaults to null). A null or empty UserName field causes
    /// the application to run as ServiceAccount.LocalService. &lt;/summary&gt;
    public string UserName { get; set; }

    /// &lt;summary&gt; The password to run the application under (defaults to null).
    /// Ignored if the UserName is empty or null, this property is ignored. &lt;/summary&gt;
    public string Password { get; set; }

    /// &lt;summary&gt;The method to start the application when the machine reboots (defaults to Automatic).&lt;/summary&gt;
    public ServiceStartMode StartMode { get; set; } = ServiceStartMode.Automatic;

    /// &lt;summary&gt; True to set the service in delayed startup. &lt;/summary&gt;
    public bool DelayedAutoStart { get; set; }

    /// &lt;summary&gt; Collects the extra arguments to be passed on the command line &lt;/summary&gt;
    public List&lt;string&gt; ExtraArgs { get; }

    /// &lt;summary&gt; Marks an IHostableApplication with configuration and installation attributes. &lt;/summary&gt;
    public WindowsServiceConfiguration(string name = null)
    {
        Name = name;
        Description = name;
        DisplayName = name;
        ExtraArgs = [&quot;run&quot;];
    }

    /// &lt;summary&gt;Returns a string that represents the Windows Service configuration.&lt;/summary&gt;
    /// &lt;returns&gt;A string that represents the current object.&lt;/returns&gt;
    public override string ToString()
    {
        return $@&quot;Name: {Name},
DisplayName: {DisplayName},
Description: {Description},
ServiceAccount: {ServiceAccount},
UserName: {UserName},
Password: {(Password == null ? string.Empty : &quot;*******&quot;)},
DelayedAutoStart: {DelayedAutoStart}
Args: {string.Join(&quot; &quot;, ExtraArgs)}
&quot;;
    }
}


[SuppressUnmanagedCodeSecurity]
public class SafeNativeMethods
{
    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern bool CloseServiceHandle(IntPtr handle);

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode)]
    public static extern int LsaClose(IntPtr objectHandle);

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode)]
    public static extern int LsaNtStatusToWinError(int ntStatus);

    [DllImport(&quot;advapi32.dll&quot;)]
    public static extern int LsaFreeMemory(IntPtr ptr);

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern IntPtr OpenSCManager(string machineName, string databaseName, int access);
}

/// &lt;summary&gt;
/// See https://github.com/microsoft/referencesource/blob/master/System.ServiceProcess/NativeMethods.cs
/// &lt;/summary&gt;
public class NativeMethods
{
    public const int STANDARD_RIGHTS_DELETE = (0x00010000);
    public const int STANDARD_RIGHTS_REQUIRED = 0x000F0000;

    public const int SC_MANAGER_CONNECT = 0x0001;
    public const int SC_MANAGER_CREATE_SERVICE = 0x0002;
    public const int SC_MANAGER_ENUMERATE_SERVICE = 0x0004;
    public const int SC_MANAGER_LOCK = 0x0008;
    public const int SC_MANAGER_MODIFY_BOOT_CONFIG = 0x0020;
    public const int SC_MANAGER_QUERY_LOCK_STATUS = 0x0010;

    public const int SC_MANAGER_ALL = STANDARD_RIGHTS_REQUIRED |
                                      SC_MANAGER_CONNECT |
                                      SC_MANAGER_CREATE_SERVICE |
                                      SC_MANAGER_ENUMERATE_SERVICE |
                                      SC_MANAGER_LOCK |
                                      SC_MANAGER_QUERY_LOCK_STATUS |
                                      SC_MANAGER_MODIFY_BOOT_CONFIG;

    public const int ACCESS_TYPE_CHANGE_CONFIG = 0x0002;
    public const int ACCESS_TYPE_ENUMERATE_DEPENDENTS = 0x0008;
    public const int ACCESS_TYPE_INTERROGATE = 0x0080;
    public const int ACCESS_TYPE_PAUSE_CONTINUE = 0x0040;
    public const int ACCESS_TYPE_QUERY_CONFIG = 0x0001;
    public const int ACCESS_TYPE_QUERY_STATUS = 0x0004;
    public const int ACCESS_TYPE_START = 0x0010;
    public const int ACCESS_TYPE_STOP = 0x0020;
    public const int ACCESS_TYPE_USER_DEFINED_CONTROL = 0x0100;

    public const int ACCESS_TYPE_ALL = STANDARD_RIGHTS_REQUIRED |
                                       ACCESS_TYPE_QUERY_CONFIG |
                                       ACCESS_TYPE_CHANGE_CONFIG |
                                       ACCESS_TYPE_QUERY_STATUS |
                                       ACCESS_TYPE_ENUMERATE_DEPENDENTS |
                                       ACCESS_TYPE_START |
                                       ACCESS_TYPE_STOP |
                                       ACCESS_TYPE_PAUSE_CONTINUE |
                                       ACCESS_TYPE_INTERROGATE |
                                       ACCESS_TYPE_USER_DEFINED_CONTROL;

    public const int SERVICE_TYPE_WIN32_OWN_PROCESS = 0x00000010;
    public const int SERVICE_TYPE_WIN32_SHARE_PROCESS = 0x00000020;

    public const int SERVICE_CONFIG_DESCRIPTION = 0x00000001;
    public const int SERVICE_CONFIG_FAILURE_ACTIONS = 0x00000002;
    public const int SERVICE_CONFIG_DELAYED_AUTO_START_INFO = 0x00000003;

    public const int ERROR_CONTROL_CRITICAL = 0x00000003;
    public const int ERROR_CONTROL_IGNORE = 0x00000000;
    public const int ERROR_CONTROL_NORMAL = 0x00000001;
    public const int ERROR_CONTROL_SEVERE = 0x00000002;

    public const int POLICY_VIEW_LOCAL_INFORMATION = 0x00000001;
    public const int POLICY_VIEW_AUDIT_INFORMATION = 0x00000002;
    public const int POLICY_GET_PRIVATE_INFORMATION = 0x00000004;
    public const int POLICY_TRUST_ADMIN = 0x00000008;
    public const int POLICY_CREATE_ACCOUNT = 0x00000010;
    public const int POLICY_CREATE_SECRET = 0x00000020;
    public const int POLICY_CREATE_PRIVILEGE = 0x00000040;
    public const int POLICY_SET_DEFAULT_QUOTA_LIMITS = 0x00000080;
    public const int POLICY_SET_AUDIT_REQUIREMENTS = 0x00000100;
    public const int POLICY_AUDIT_LOG_ADMIN = 0x00000200;
    public const int POLICY_SERVER_ADMIN = 0x00000400;
    public const int POLICY_LOOKUP_NAMES = 0x00000800;

    public const int STATUS_OBJECT_NAME_NOT_FOUND = -1073741772; //0xC0000034;
    public const int MAX_COMPUTERNAME_LENGTH = 31;

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public class LSA_UNICODE_STRING_withPointer
    {
        public short length;

        public short maximumLength;

        public IntPtr pwstr = 0;
    }

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public class LSA_UNICODE_STRING
    {
        public short length;

        public short maximumLength;

        public string buffer;
    }

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public class LSA_OBJECT_ATTRIBUTES
    {
        public int length;

        public IntPtr rootDirectory = 0;

        public IntPtr pointerLsaString = 0;

        public int attributes;

        public IntPtr pointerSecurityDescriptor = 0;

        public IntPtr pointerSecurityQualityOfService = 0;
    }

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public struct SERVICE_DELAYED_AUTOSTART_INFO
    {
        public bool fDelayedAutostart;
    }

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public struct SERVICE_DESCRIPTION
    {
        public IntPtr description;
    }

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern bool ChangeServiceConfig2(IntPtr serviceHandle, uint infoLevel,
        ref SERVICE_DESCRIPTION serviceDesc);

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern bool ChangeServiceConfig2(IntPtr serviceHandle, uint infoLevel,
        ref SERVICE_DELAYED_AUTOSTART_INFO serviceDesc);

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern IntPtr CreateService(IntPtr databaseHandle, string serviceName, string displayName, int access,
        int serviceType, int startType, int errorControl, string binaryPath, string loadOrderGroup, IntPtr pTagId,
        string dependencies, string servicesStartName, string password);

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern bool LookupAccountName(string systemName, string accountName, byte[] sid, int[] sidLen,
        char[] refDomainName, int[] domNameLen, [In] [Out] int[] sidNameUse);

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode)]
    public static extern int LsaAddAccountRights(IntPtr policyHandle, byte[] accountSid, LSA_UNICODE_STRING userRights,
        int countOfRights);

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode)]
    public static extern int LsaEnumerateAccountRights(IntPtr policyHandle, byte[] accountSid,
        out IntPtr pLsaUnicodeStringUserRights, out int RightsCount);

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode)]
    public static extern int LsaOpenPolicy(LSA_UNICODE_STRING systemName, IntPtr pointerObjectAttributes,
        int desiredAccess, out IntPtr pointerPolicyHandle);

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode)]
    public static extern int LsaRemoveAccountRights(IntPtr policyHandle, byte[] accountSid, bool allRights,
        LSA_UNICODE_STRING userRights, int countOfRights);

    [DllImport(&quot;kernel32.dll&quot;, CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern bool GetComputerName(StringBuilder lpBuffer, ref int nSize);

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern bool DeleteService(IntPtr serviceHandle);

    [DllImport(&quot;advapi32.dll&quot;, CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern IntPtr OpenService(IntPtr databaseHandle, string serviceName, int access);
}
</code></pre>
<p>To use it, you create an instance of <code>WindowsServiceConfiguration</code> and just pass it to <code>WindowsServiceInstaller.Install</code>.</p>
